guidedExercise.solutionCode:
def validate_fence(current_token, worker_token):
    if worker_token != current_token:
        raise PermissionError('stale worker fence')
    return True

guidedExercise.unitTests:
assert validate_fence(13, 13)
try:
    validate_fence(13, 12)
    raise AssertionError('stale worker must be rejected')
except PermissionError:
    pass
